import React from "react";

export default function CameraFeed({ latestFrame, cameraAlert, engineOnline }) {
  const card = {
    background: "#1a1d27", borderRadius: 12,
    border: "1px solid #2a2d3a", overflow: "hidden",
  };

  return (
    <div style={card}>
      <div style={{ padding: "12px 16px", borderBottom: "1px solid #2a2d3a",
                    fontSize: 13, fontWeight: 600, color: "#9ca3af", letterSpacing: 0.5 }}>
        LIVE FEED
      </div>

      <div style={{ position: "relative", background: "#0a0c12", minHeight: 280 }}>
        {latestFrame?.image ? (
          <img
            src={`data:image/jpeg;base64,${latestFrame.image}`}
            alt="Live camera feed"
            style={{ width: "100%", display: "block", borderRadius: 0 }}
          />
        ) : (
          <div style={{
            display: "flex", alignItems: "center", justifyContent: "center",
            height: 280, color: "#4b5563", fontSize: 13, flexDirection: "column", gap: 8,
          }}>
            <div style={{ width: 40, height: 40, borderRadius: "50%",
                          border: "2px solid #2a2d3a", display: "flex",
                          alignItems: "center", justifyContent: "center", fontSize: 18 }}>
              ◎
            </div>
            {engineOnline ? "Waiting for frames..." : "Detection engine offline"}
          </div>
        )}

        {/* Detection box overlays */}
        {latestFrame?.detections?.map((det, i) => (
          <div key={i} style={{
            position: "absolute",
            left:   `${(det.bbox[0] / 640) * 100}%`,
            top:    `${(det.bbox[1] / 480) * 100}%`,
            width:  `${((det.bbox[2] - det.bbox[0]) / 640) * 100}%`,
            height: `${((det.bbox[3] - det.bbox[1]) / 480) * 100}%`,
            border: `2px solid ${det.brand_matched ? "#22c55e" : "#f59e0b"}`,
            borderRadius: 3, pointerEvents: "none",
          }}>
            <span style={{
              position: "absolute", top: -20, left: 0, fontSize: 11, fontWeight: 600,
              background: det.brand_matched ? "#22c55e" : "#f59e0b",
              color: "#000", padding: "1px 5px", borderRadius: 3, whiteSpace: "nowrap",
            }}>
              {det.class} {(det.confidence * 100).toFixed(0)}%
            </span>
          </div>
        ))}

        {/* Camera alert banner */}
        {cameraAlert && (
          <div style={{
            position: "absolute", bottom: 0, left: 0, right: 0,
            background: "rgba(239,68,68,0.9)", color: "#fff",
            padding: "8px 14px", fontSize: 13, fontWeight: 500,
          }}>
            Camera alert: {cameraAlert.reason} (lum: {cameraAlert.luminance})
          </div>
        )}
      </div>

      {latestFrame && (
        <div style={{ padding: "8px 16px", fontSize: 11, color: "#6b7280",
                      borderTop: "1px solid #2a2d3a" }}>
          Last frame: {new Date(latestFrame.timestamp * 1000).toLocaleTimeString()} ·{" "}
          {latestFrame.detections?.length ?? 0} detection(s)
        </div>
      )}
    </div>
  );
}
